# 2) Custom CUDA kernel for transposed 1D convolution (naïve implementation)
# ----------------------------------------------------------------------
conv_transpose1d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* __restrict__ input,   // [N, C_in, L]
    const float* __restrict__ weight, // [C_out, K, D]  (D = dilation)
    float* __restrict__ output,       // [N, C_out, L_out]
    int N, int C_in, int L,
    int C_out, int K, int D) {
    const int L_out = (L - 1) * K * D;   // placeholder for stride=1, padding=0

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * C_out * L_out) {
        int n = idx / (C_out * L_out);
        int rem = idx % (C_out * L_out);
        int c_out = rem / L_out;
        int l_pos = rem % L_out;

        float sum = 0.0f;
        for (int ic = 0; ic < C_in; ++ic) {
            // Input sample index: n*C_in*L + ic*K*D + l_pos
            int in_idx = n * C_in * L + ic * K * D + l_pos;
            if (in_idx < N * C_in * L) {   // guard
                sum += weight[c_out][ic] * input[in_idx];
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv_transpose1d_cuda(torch::Tensor input, torch::Tensor weight,
                                     int stride, int padding, int dilation) {
    auto N = input.size(0);
    auto C_in = input.size(1);
    auto L = input.size(2);

    // Kernel size and dilation are taken from the weight tensor shape [C_out, K, D]
    auto out_channels = weight.shape()[0];
    auto K = weight.shape()[1];
    auto D = weight.shape()[2];

    // Output length (assuming stride=1, padding=0)
    auto out_len = (L - 1) * K * D;   // placeholder formula

    // Allocate output tensor with zeros_like input but reshape to [N, out_channels, out_len]
    auto total_elements = N * out_channels * out_len;
    auto out = torch::zeros(total_elements);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose1d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float()>,
                                                          out.data_ptr<float()>, N, C_in, L,
                                                          out_channels, K, D);

    // Reshape to [N, out_channels, out_len]
    auto out_tensor = torch::from_blob(out.data_ptr<float>(), total_elements, (N, out_channels, out_len)).contiguous().cuda();
    return out_tensor;
}
"""

conv_transpose1d_cuda = load_inline(
    name="conv_transpose1d",
    cpp_sources=["torch::Tensor conv_transpose1d_cuda(torch::Tensor input, torch::Tensor weight, int stride, int padding, int dilation);"],
    cuda_sources=conv_transpose1d_kernel_source,
    functions=["conv_transpose1d_cuda"],
    verbose=True,
)

