# 3) Optimized model (ModelNew)
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int = 32, out_channels: int = 64, kernel_size: int = 5,
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False) -> None:
        super().__init__()
        self.conv1d_transpose = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, stride=stride,
                                                    padding=padding, dilation=dilation, bias=bias)
        # Attach the custom CUDA operator for transposed convolution
        self.conv_transpose_cuda = conv_transpose1d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 1D convolution using the custom CUDA kernel.
        """
        # Build weight tensor matching (out_channels, kernel_size, dilation)
        weight = torch.zeros(self.conv1d_transpose.out_channels,
                             self.conv1d_transpose.kernel_size,
                             self.conv1d_transpose.dilation).float()
        out = self.conv_transpose_cuda(x, weight, stride=self.conv1d_transpose.stride,
                                        padding=self.conv1d_transpose.padding,
                                        dilation=self.conv1d_transpose.dilation)
        return out
